CREATE TABLE `invoices` (
  `id` int NOT NULL AUTO_INCREMENT,
  `create_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `invoiceType` enum('CONTADO','CREDITO') NOT NULL DEFAULT 'CONTADO',
  `paymentStatus` enum('PENDIENTE','PAGADA') NOT NULL DEFAULT 'PENDIENTE',
  `total` decimal(10,2) NOT NULL DEFAULT '0.00',
  `isDisable` tinyint NOT NULL DEFAULT '0',
  `bookingId` int DEFAULT NULL,
  `customerId` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_eca01fda44679cc1c342822e01b` (`bookingId`),
  KEY `FK_1df049f8943c6be0c1115541efb` (`customerId`),
  CONSTRAINT `FK_1df049f8943c6be0c1115541efb` FOREIGN KEY (`customerId`) REFERENCES `customers` (`id`),
  CONSTRAINT `FK_eca01fda44679cc1c342822e01b` FOREIGN KEY (`bookingId`) REFERENCES `bookings` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
